class MockSensor:
    def __init__(self, mode='reschedule'):
        self.mode = mode
        self.worker_slot_locked = False

    def poke_condition(self, exists):
        if exists:
            self.worker_slot_locked = False
            return 'SUCCESS'
        if self.mode == 'poke':
            self.worker_slot_locked = True
            return 'SLEEPING_BUT_LOCKED'
        else:
            self.worker_slot_locked = False
            return 'UP_FOR_RESCHEDULE'

s_poke = MockSensor(mode='poke')
s_resched = MockSensor(mode='reschedule')

print('Poke con archivo ausente:', s_poke.poke_condition(False), '| Slot bloqueado:', s_poke.worker_slot_locked)
print('Reschedule con archivo ausente:', s_resched.poke_condition(False), '| Slot bloqueado:', s_resched.worker_slot_locked)
